#include <stdio.h>

typedef struct {
    int items[10];
    int size;
} Stack;

void push(Stack *s, int value) {
    s->items[s->size++] = value;
}

int pop(Stack *s) {
    return s->items[--s->size];
}

int main() {
    Stack stack = {{0}, 0};
    push(&stack, 5);
    push(&stack, 8);
    push(&stack, 13);
    while (stack.size > 0) {
        printf("%d\n", pop(&stack));
    }
    return 0;
}
